  /**
   * The first frame's number.
   */
  startFrame: number;
  /**
   * How much the frame number advances per frame.
   */
  frameStep: number;
  /**
   * The sequence's frame rate.
   */
  rate: number;
  /**
   * How many digits the frame number is padded to.
   */
